<?php
declare(strict_types=1);
namespace App\Controllers\Api;
use CodeIgniter\HTTP\ResponseInterface;

class LabourAttendanceController extends LabourApiController
{
 public function index():ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$b=db_connect()->table('labour_attendance_batches b')->select('b.*,p.project_code,p.project_name,s.site_code,s.site_name,st.status_code,st.status_name')->join('projects p','p.id=b.project_id')->join('project_sites s','s.id=b.site_id')->join('labour_attendance_batches_status_masters st','st.id=b.status_id')->where('b.company_id',$this->companyId($u));foreach(['project_id','site_id','status_id']as$f)if(ctype_digit((string)($this->request->getGet($f)??'')))$b->where('b.'.$f,(int)$this->request->getGet($f));if(ctype_digit((string)($this->request->getGet('subcontractor_id')??''))){$sub=(int)$this->request->getGet('subcontractor_id');$ids=db_connect()->table('labour_attendance_entries e')->distinct()->select('e.batch_id')->join('labour_workers w','w.id=e.worker_id AND w.company_id=e.company_id')->join('labour_contractors lc','lc.id=w.contractor_id AND lc.company_id=w.company_id')->where('e.company_id',$this->companyId($u))->where('lc.subcontractor_id',$sub)->get()->getResultArray();$batchIds=array_column($ids,'batch_id');if(!$batchIds)return$this->ok('Attendance batches retrieved successfully.','attendance_batches',[]);$b->whereIn('b.id',$batchIds);}foreach(['date_from'=>'>=','date_to'=>'<=']as$f=>$op)if($this->request->getGet($f))$b->where('b.attendance_date '.$op,$this->request->getGet($f));return$this->ok('Attendance batches retrieved successfully.','attendance_batches',$b->orderBy('b.attendance_date','DESC')->orderBy('b.id','DESC')->get()->getResultArray());}
 public function show(int$id):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$b=$this->record('labour_attendance_batches',$id,$this->companyId($u));if(!$b)return$this->notFound();$b['entries']=db_connect()->table('labour_attendance_entries e')->select('e.*,w.worker_code,w.worker_name,lc.id AS contractor_id,lc.contractor_code,lc.contractor_name,lc.subcontractor_id,sc.contractor_code AS subcontractor_code,sc.contractor_name AS subcontractor_name,s.attendance_status_code,s.attendance_status_name')->join('labour_workers w','w.id=e.worker_id')->join('labour_contractors lc','lc.id=w.contractor_id AND lc.company_id=w.company_id','left')->join('subcontractors sc','sc.id=lc.subcontractor_id AND sc.company_id=lc.company_id','left')->join('labour_attendance_entries_attendance_status_masters s','s.id=e.attendance_status_id')->where('e.batch_id',$id)->orderBy('w.worker_name')->get()->getResultArray();return$this->ok('Attendance batch retrieved successfully.','attendance_batch',$b);}
 public function create():ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$in=$this->input();if(!$in)return$this->invalid(['body'=>'A valid JSON request body is required.']);$e=$this->required($in,['project_id','site_id','attendance_date']);if(!$this->site((int)($in['site_id']??0),(int)($in['project_id']??0),$u,true))$e['site_id']='Select an accessible site belonging to the project.';$draft=$this->masterId('labour_attendance_batches_status_masters','status_code','DRAFT');if(!$draft)$e['status']='DRAFT attendance status is not configured.';if($e)return$this->invalid($e);$d=array_intersect_key($in,array_flip(['project_id','site_id','attendance_date','shift_code','remarks']));$d+=['company_id'=>$this->companyId($u),'shift_code'=>'GENERAL','status_id'=>$draft,'created_by'=>(int)$u->id,'updated_by'=>(int)$u->id,'created_at'=>$this->now(),'updated_at'=>$this->now()];if(db_connect()->table('labour_attendance_batches')->where(['company_id'=>$d['company_id'],'project_id'=>$d['project_id'],'site_id'=>$d['site_id'],'attendance_date'=>$d['attendance_date'],'shift_code'=>$d['shift_code']])->countAllResults())return$this->invalid(['attendance_date'=>'An attendance batch already exists for this site, date and shift.']);db_connect()->table('labour_attendance_batches')->insert($d);$id=(int)db_connect()->insertID();return$this->ok('Attendance batch created successfully.','attendance_batch',$this->record('labour_attendance_batches',$id,$d['company_id']),201);}
 public function entries(int$batchId):ResponseInterface{return$this->show($batchId);}
 public function saveEntry(int$batchId,?int$entryId=null):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$c=$this->companyId($u);$batch=$this->record('labour_attendance_batches',$batchId,$c);if(!$batch)return$this->notFound();$status=$this->statusCode((int)$batch['status_id']);if(!in_array($status,['DRAFT','REJECTED'],true))return$this->response->setStatusCode(409)->setJSON(['success'=>false,'message'=>'Attendance entries can be changed only in Draft or Rejected status.']);$in=$this->input();if(!$in)return$this->invalid(['body'=>'A valid JSON request body is required.']);$old=$entryId?$this->record('labour_attendance_entries',$entryId,$c):null;if($entryId&&(!$old||(int)$old['batch_id']!==$batchId))return$this->notFound();$fields=['assignment_id','worker_id','zone_id','attendance_status_id','check_in_time','check_out_time','regular_hours','overtime_hours','work_description','attendance_source_id','latitude','longitude','selfie_path','remarks'];$d=array_intersect_key($in,array_flip($fields));$m=array_merge($old??[],$d);$e=$this->required($m,['assignment_id','worker_id','attendance_status_id','attendance_source_id']);$a=$this->record('labour_project_assignments',(int)($m['assignment_id']??0),$c,true);if(!$a||(int)$a['worker_id']!==(int)($m['worker_id']??0)||(int)$a['project_id']!==(int)$batch['project_id']||(int)$a['site_id']!==(int)$batch['site_id'])$e['assignment_id']='Select a valid worker assignment for this project and site.';if(!$this->activeMaster('labour_attendance_entries_attendance_status_masters',(int)($m['attendance_status_id']??0)))$e['attendance_status_id']='Select a valid attendance status.';if(!$this->activeMaster('labour_attendance_entries_attendance_source_masters',(int)($m['attendance_source_id']??0)))$e['attendance_source_id']='Select a valid attendance source.';if($e)return$this->invalid($e);$d['updated_by']=(int)$u->id;$d['updated_at']=$this->now();if(!$entryId)$d+=['company_id'=>$c,'batch_id'=>$batchId,'created_by'=>(int)$u->id,'created_at'=>$this->now()];$b=db_connect()->table('labour_attendance_entries');$entryId?$b->where('id',$entryId)->update($d):$b->insert($d);$entryId??=(int)db_connect()->insertID();$this->recalc($batchId);return$this->ok($old?'Attendance entry updated successfully.':'Attendance entry created successfully.','attendance_entry',$this->record('labour_attendance_entries',$entryId,$c),$old?200:201);}
 public function createEntry(int$b):ResponseInterface{return$this->saveEntry($b);}public function updateEntry(int$b,int$e):ResponseInterface{return$this->saveEntry($b,$e);}public function deleteEntry(int$b,int$e):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$batch=$this->record('labour_attendance_batches',$b,$this->companyId($u));$entry=$this->record('labour_attendance_entries',$e,$this->companyId($u));if(!$batch||!$entry||(int)$entry['batch_id']!==$b)return$this->notFound();if(!in_array($this->statusCode((int)$batch['status_id']),['DRAFT','REJECTED'],true))return$this->response->setStatusCode(409)->setJSON(['success'=>false,'message'=>'Entries cannot be deleted in the current status.']);db_connect()->table('labour_attendance_entries')->where('id',$e)->delete();$this->recalc($b);return$this->response->setJSON(['success'=>true,'message'=>'Attendance entry deleted successfully.']);}
 public function submit(int$id):ResponseInterface{return$this->transition($id,'DRAFT','SUBMITTED','SUBMIT');}public function approve(int$id):ResponseInterface{return$this->transition($id,'SUBMITTED','APPROVED','APPROVE');}public function reject(int$id):ResponseInterface{return$this->transition($id,'SUBMITTED','REJECTED','REJECT');}public function lock(int$id):ResponseInterface{return$this->transition($id,'APPROVED','LOCKED','LOCK');}
 private function transition(int$id,string$from,string$to,string$action):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$c=$this->companyId($u);$r=$this->record('labour_attendance_batches',$id,$c);if(!$r)return$this->notFound();$old=$this->statusCode((int)$r['status_id']);if($old!==$from&&!( $action==='SUBMIT'&&$old==='REJECTED'))return$this->response->setStatusCode(409)->setJSON(['success'=>false,'message'=>'Invalid attendance status transition from '.$old.' to '.$to.'.']);if($action==='SUBMIT'&&db_connect()->table('labour_attendance_entries')->where('batch_id',$id)->countAllResults()===0)return$this->invalid(['entries'=>'Add at least one attendance entry before submission.']);$sid=$this->masterId('labour_attendance_batches_status_masters','status_code',$to);if(!$sid)return$this->response->setStatusCode(500)->setJSON(['success'=>false,'message'=>$to.' status is not configured.']);$in=$this->input()??[];$d=['status_id'=>$sid,'remarks'=>$in['remarks']??$r['remarks'],'updated_by'=>(int)$u->id,'updated_at'=>$this->now()];if($to==='SUBMITTED')$d+=['prepared_by'=>(int)$u->id,'prepared_at'=>$this->now()];if($to==='APPROVED')$d+=['approved_by'=>(int)$u->id,'approved_at'=>$this->now()];db_connect()->table('labour_attendance_batches')->where('id',$id)->update($d);$this->statusLog($c,'ATTENDANCE',$id,$old,$to,$action,$in['remarks']??null,(int)$u->id);return$this->ok('Attendance batch '.strtolower($to).' successfully.','attendance_batch',$this->record('labour_attendance_batches',$id,$c));}
 private function statusCode(int$id):string{$r=db_connect()->table('labour_attendance_batches_status_masters')->select('status_code')->where('id',$id)->get()->getRowArray();return(string)($r['status_code']??'UNKNOWN');}
 private function recalc(int$id):void{$r=db_connect()->table('labour_attendance_entries e')->select("COUNT(*) total_workers,SUM(CASE WHEN s.attendance_status_code IN ('PRESENT','HALF_DAY') THEN 1 ELSE 0 END) present_workers,SUM(CASE WHEN s.attendance_status_code='ABSENT' THEN 1 ELSE 0 END) absent_workers,COALESCE(SUM(e.regular_hours),0) total_regular_hours,COALESCE(SUM(e.overtime_hours),0) total_overtime_hours",false)->join('labour_attendance_entries_attendance_status_masters s','s.id=e.attendance_status_id')->where('e.batch_id',$id)->get()->getRowArray();db_connect()->table('labour_attendance_batches')->where('id',$id)->update($r);}
}
